if "complete-dark-theme-v315" not in html:
    pos=html.rfind("</body>")
    if pos<0: raise SystemExit("Missing closing body tag")
    html=html[:pos]+style+"\n"+html[pos:]
html_path.write_text(html,encoding="utf-8")
build=build_path.read_text(encoding="utf-8")
build=re.sub(r"versionCode\s+\d+","versionCode 18",build)
